function splitLines(t){ return String(t).replace(/\r\n/g,'\n').replace(/\r/g,'\n').split('\n'); }
function joinLines(a){ return a.join('\n'); }
function dedupe(t){ var seen={}, out=[]; splitLines(t).forEach(function(l){ if(!Object.prototype.hasOwnProperty.call(seen,l)){ seen[l]=1; out.push(l); } }); return joinLines(out); }
function removeEmpty(t){ return joinLines(splitLines(t).filter(function(l){ return l.trim()!==''; })); }
function sortLines(t, desc){ var a=splitLines(t).slice().sort(); if(desc) a.reverse(); return joinLines(a); }
function reverseLines(t){ return joinLines(splitLines(t).slice().reverse()); }
function trimLines(t){ return joinLines(splitLines(t).map(function(l){ return l.trim(); })); }
function numberLines(t, start){ start=(start==null||isNaN(Number(start)))?1:Number(start); return joinLines(splitLines(t).map(function(l,i){ return (start+i)+'. '+l; })); }
function countStats(t){ var lines=splitLines(t); return { lines:lines.length, chars:String(t).length, words:String(t).split(/\s+/).filter(Boolean).length }; }
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { splitLines:splitLines, joinLines:joinLines, dedupe:dedupe, removeEmpty:removeEmpty, sortLines:sortLines, reverseLines:reverseLines, trimLines:trimLines, numberLines:numberLines, countStats:countStats };
}
if (typeof window !== 'undefined') {
  window.LinesForgePure = { splitLines:splitLines, joinLines:joinLines, dedupe:dedupe, removeEmpty:removeEmpty, sortLines:sortLines, reverseLines:reverseLines, trimLines:trimLines, numberLines:numberLines, countStats:countStats };
}
